#include <cstdio>
using namespace std;

int main() {
    int n, s;
    while (scanf("%d %d", &n, &s) == 2 && n) {
        int r[101] = {0};
        for (int i = 0; i < n; i++) {
            int tmp;
            scanf("%d", &tmp);
            r[tmp]++;
        }

        int ans = 0;
        for (int i = 0; i <= 100; i++) {
            if (i + i > s) ans += (r[i] * (r[i] - 1)) / 2; // counting pairs of the same number
        }

        // Optimize the pair counting with a single loop
        for (int i = 0; i <= 100; i++) {
            if (r[i] > 0) {
                for (int j = i + 1; j <= 100; j++) {
                    if (r[j] > 0 && i + j > s) {
                        ans += r[i] * r[j]; // counting pairs of different numbers
                    }
                }
            }
        }
        printf("%d\n", ans);
    }
    return 0;
}

